// OTHVM Streaks Callback — inline buttons (stk|done / stk|miss) -> update streak + reply. No LLM.
// NOTE: keep the complete/miss logic in sync with System — Streaks (complete op).
const base = String($env.SUPABASE_URL ?? '');
const key = String($env.SUPABASE_SERVICE_KEY ?? '');
const TG = 'REPLACE_WITH_TELEGRAM_BOT_TOKEN';
const CHAT = 'REPLACE_WITH_TELEGRAM_CHAT_ID';
if (!base || !key) return [{ json: { ok: false, error: 'Supabase env vars missing in the n8n environment' } }];
const HB = { apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json', Accept: 'application/json' };
const hreq = async (o) => {
  const opts = Object.assign({ returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 25000 }, o);
  try { return await this.helpers.httpRequest(opts); } catch (e) { return { statusCode: 0, body: 'ERR ' + (e && e.message ? e.message : String(e)) }; }
};
const parse = (r) => { let d = r.body; if (typeof d === 'string' && d.length) { try { d = JSON.parse(d); } catch (e) {} } return { st: r.statusCode ?? 0, d }; };
const errOf = (r) => { const d = r.d; if (d && typeof d === 'object' && (d.message || d.hint)) return String(d.message) + (d.hint ? ' — ' + String(d.hint) : ''); return String(typeof d === 'string' ? d : JSON.stringify(d || '')).slice(0, 240); };
const cairoToday = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
try {
  const body = $json.body || $json;
  const cq = body && body.callback_query ? body.callback_query : body;
  const data = String((cq && cq.data) || '');
  const parts = data.split('|');
  if (parts.length !== 3 || parts[0] !== 'stk') return [{ json: { ok: true, skipped: true, data: data.slice(0, 40) } }];
  const action = parts[1];
  const streakId = parts[2];
  const cqId = cq.id || null;
  const chatId = (cq.message && cq.message.chat && cq.message.chat.id) ? String(cq.message.chat.id) : CHAT;
  const msgId = cq.message ? cq.message.message_id : null;
  const toast = async (t) => { if (cqId) await hreq({ method: 'POST', url: 'https://api.telegram.org/bot' + TG + '/answerCallbackQuery', headers: { 'Content-Type': 'application/json' }, body: { callback_query_id: cqId, text: t }, json: true }); };
  const send = async (t) => hreq({ method: 'POST', url: 'https://api.telegram.org/bot' + TG + '/sendMessage', headers: { 'Content-Type': 'application/json' }, body: { chat_id: chatId, text: t }, json: true });

  const today = cairoToday();
  const gr = parse(await hreq({ method: 'GET', url: base + '/rest/v1/streaks?select=*&id=eq.' + encodeURIComponent(streakId) + '&limit=1', headers: HB, json: true }));
  if (gr.st <= 0 || gr.st >= 300 || !Array.isArray(gr.d) || !gr.d[0]) { await toast('مش لاقي السلسلة دي 🤔'); return [{ json: { ok: false, error: 'streak not found: ' + streakId } }]; }
  const s = gr.d[0];
  const lr = parse(await hreq({ method: 'GET', url: base + '/rest/v1/streak_logs?select=status&streak_id=eq.' + encodeURIComponent(streakId) + '&log_date=eq.' + today + '&limit=1', headers: HB, json: true }));
  const existing = (lr.st > 0 && lr.st < 300 && Array.isArray(lr.d) && lr.d[0]) ? lr.d[0].status : null;
  if (msgId) await hreq({ method: 'POST', url: 'https://api.telegram.org/bot' + TG + '/editMessageReplyMarkup', headers: { 'Content-Type': 'application/json' }, body: { chat_id: chatId, message_id: msgId, reply_markup: { inline_keyboard: [] } }, json: true });
  const upsertLog = async (status) => hreq({ method: 'POST', url: base + '/rest/v1/streak_logs?on_conflict=streak_id,log_date', headers: Object.assign({}, HB, { Prefer: 'resolution=merge-duplicates,return=minimal' }), body: { streak_id: streakId, log_date: today, status: status }, json: true });

  if (action === 'done') {
    if (existing === 'completed') { await toast('مسجّل بالفعل ✅'); return [{ json: { ok: true, already: true, name: s.name } }]; }
    const n = Number(s.current_streak || 0) + 1;
    const longest = Math.max(Number(s.longest_streak || 0), n);
    await hreq({ method: 'PATCH', url: base + '/rest/v1/streaks?id=eq.' + encodeURIComponent(streakId), headers: Object.assign({}, HB, { Prefer: 'return=minimal' }), body: { current_streak: n, longest_streak: longest, last_completed: today, updated_at: new Date().toISOString() }, json: true });
    await upsertLog('completed');
    await toast('تمام يا وحش! 🔥');
    await send('🎉 ' + s.name + ' — سلسلة ' + n + ' يوم متواصلة! كمّل كده 🔥');
    return [{ json: { ok: true, action: 'done', name: s.name, current_streak: n } }];
  }

  if (action === 'miss') {
    if (existing === 'completed') { await toast('مسجّلة خلاص ✅'); return [{ json: { ok: true, already: true, name: s.name } }]; }
    await hreq({ method: 'PATCH', url: base + '/rest/v1/streaks?id=eq.' + encodeURIComponent(streakId), headers: Object.assign({}, HB, { Prefer: 'return=minimal' }), body: { current_streak: 0, updated_at: new Date().toISOString() }, json: true });
    await upsertLog('missed');
    await toast('ولا يهمك 💙');
    await send('💙 ' + s.name + ' — ولا يهمك يا المستخدم، بكرة يوم جديد وإحنا نبدأ من 1 مع بعض! 💪');
    return [{ json: { ok: true, action: 'miss', name: s.name, current_streak: 0 } }];
  }

  await toast('حاجة غريبة 🤔');
  return [{ json: { ok: false, error: 'unknown action: ' + action } }];
} catch (e) {
  return [{ json: { ok: false, error: 'خطأ: ' + String(e && e.message ? e.message : e).slice(0, 300) } }];
}
